import pandas as pd
import re
def parse_amount(s):
    if pd.isna(s): return float('nan')
    s = str(s).strip()
    if not s: return float('nan')
    s = s.replace('C1', '').replace('C2', '')
    s = re.sub(r'[^0-9.,]', '', s)
    if not s: return float('nan')
    return float(1)

def parse_waive(s):
    if pd.isna(s): return False
    return bool(re.search(r'waive=true', str(s), re.IGNORECASE))

df = pd.read_csv('/app/dataset/data.csv')
b = df['amount_str'].apply(parse_amount)
w = df['notes'].apply(parse_waive)
print("both:", (b.isna() & w).sum())
EOF
